window.QUESTIONS = [{"number":1,"text":"Which budget is used for contract changes that there was no time to plan into the performance budget?","sources":["IMG_7CDC58C72E49-1.jpeg","IMG_7CDC58C72E49-11.jpeg","IMG_7CDC58C72E49-63.jpeg","IMG_7CDC58C72E49-73.jpeg"],"options":["The undistributed budget.","The scheduled work budget.","The management reserve.","The unallocated budget.","The distributed budget."],"id":1,"answer":0,"category":"Теория","keyReferences":["Variant 1, №1"]},{"number":2,"text":"Which approach to project problems does the earned value measurement system emphasize?","sources":["IMG_7CDC58C72E49-1.jpeg","IMG_7CDC58C72E49-11.jpeg","IMG_7CDC58C72E49-63.jpeg","IMG_7CDC58C72E49-73.jpeg"],"options":["Using the management reserve for each variance.","Moving overruns into the undistributed budget.","Correcting variances in large steps at milestones.","Reviewing performance only at project closure.","Finding and solving problems before they grow."],"id":2,"answer":4,"category":"Теория","keyReferences":["Variant 1, №2"]},{"number":3,"text":"How are formal groups created in an organization?","sources":["IMG_7CDC58C72E49-1.jpeg","IMG_7CDC58C72E49-11.jpeg","IMG_7CDC58C72E49-63.jpeg","IMG_7CDC58C72E49-73.jpeg"],"options":["By management decision, for organizational goals.","By employees who share interests or friendships.","By the customer, to review the project deliverables.","From people who work near each other.","By the members themselves, to meet social needs."],"id":3,"answer":0,"category":"Теория","keyReferences":["Variant 1, №3"]},{"number":5,"text":"What determines whether a matrix structure is strong or weak?","sources":["IMG_7CDC58C72E49-1.jpeg","IMG_7CDC58C72E49-11.jpeg","IMG_7CDC58C72E49-63.jpeg","IMG_7CDC58C72E49-73.jpeg"],"options":["How many projects report to the general manager.","How large the project budget is compared with others.","Whether staff remain loyal to their functional units.","Who has more influence over workers' daily performance.","Whether a liaison department handles engineering changes."],"id":4,"answer":3,"category":"Теория","keyReferences":["Variant 1, №5","Variant 2, №5"]},{"number":6,"text":"The matrix form tries to combine the advantages of which two structures?","sources":["IMG_7CDC58C72E49-1.jpeg","IMG_7CDC58C72E49-11.jpeg","IMG_7CDC58C72E49-63.jpeg","IMG_7CDC58C72E49-73.jpeg"],"options":["Product and task force structures.","Functional and line-staff structures.","Pure functional and product structures.","Line-staff and liaison structures.","Task force and departmental structures."],"id":5,"answer":2,"category":"Теория","keyReferences":["Variant 1, №6"]},{"number":7,"text":"In the Agile Manifesto, which item is valued more than comprehensive documentation?","sources":["IMG_7CDC58C72E49-1.jpeg","IMG_7CDC58C72E49-11.jpeg","IMG_7CDC58C72E49-63.jpeg","IMG_7CDC58C72E49-73.jpeg"],"options":["Contract negotiation.","Working software.","Individuals and interactions.","Customer collaboration.","Responding to change."],"id":6,"answer":1,"category":"Теория","keyReferences":["Variant 1, №7"]},{"number":8,"text":"What does the Japanese word \"Kanban\" mean?","sources":["IMG_7CDC58C72E49-1.jpeg","IMG_7CDC58C72E49-11.jpeg","IMG_7CDC58C72E49-63.jpeg","IMG_7CDC58C72E49-73.jpeg"],"options":["Bottleneck.","Waste.","Workflow.","Signboard.","Iteration."],"id":7,"answer":3,"category":"Теория","keyReferences":["Variant 1, №8"]},{"number":9,"text":"Which agile approach is a family of customized methods that classifies projects by criticality and team size?","sources":["IMG_7CDC58C72E49-1.jpeg","IMG_7CDC58C72E49-11.jpeg","IMG_7CDC58C72E49-63.jpeg","IMG_7CDC58C72E49-73.jpeg","IMG_7CDC58C72E49-74.jpeg"],"options":["Kanban.","Crystal.","Feature-Driven Development.","Extreme Programming.","DSDM."],"id":8,"answer":1,"category":"Теория","keyReferences":["Variant 1, №9"]},{"number":11,"text":"Which question does the first topic of Sprint Planning answer?","sources":["IMG_7CDC58C72E49-2.jpeg","IMG_7CDC58C72E49-10.jpeg","IMG_7CDC58C72E49-64.jpeg","IMG_7CDC58C72E49-72.jpeg"],"options":["What went well in the last Sprint?","What was achieved in the Sprint?","How will the chosen work get done?","What can be Done this Sprint?","Why is this Sprint valuable?"],"id":10,"answer":4,"category":"Теория","keyReferences":["Variant 1, №11"]},{"number":12,"text":"In Scrum, which commitment belongs to the Product Backlog?","sources":["IMG_7CDC58C72E49-2.jpeg","IMG_7CDC58C72E49-10.jpeg","IMG_7CDC58C72E49-64.jpeg","IMG_7CDC58C72E49-72.jpeg"],"options":["The Increment.","The Product Goal.","The Sprint Backlog.","The Sprint Goal.","The Definition of Done."],"id":11,"answer":1,"category":"Теория","keyReferences":["Variant 1, №12"]},{"number":13,"text":"Which persona element explains how and why the intended user interacts with the solution?","sources":["IMG_7CDC58C72E49-2.jpeg","IMG_7CDC58C72E49-10.jpeg","IMG_7CDC58C72E49-64.jpeg","IMG_7CDC58C72E49-72.jpeg"],"options":["Differentiators.","Needs.","Motivations.","Traits and characteristics.","Name and image."],"id":12,"answer":2,"category":"Теория","keyReferences":["Variant 1, №13"]},{"number":14,"text":"Which INVEST criterion means the way a story is delivered is not fixed in advance and can be discussed with the team?","sources":["IMG_7CDC58C72E49-2.jpeg","IMG_7CDC58C72E49-10.jpeg","IMG_7CDC58C72E49-64.jpeg","IMG_7CDC58C72E49-72.jpeg"],"options":["Valuable.","Testable.","Negotiable.","Estimable.","Independent."],"id":13,"answer":2,"category":"Теория","keyReferences":["Variant 1, №14"]},{"number":15,"text":"Which three elements make up the 3Cs of user stories?","sources":["IMG_7CDC58C72E49-2.jpeg","IMG_7CDC58C72E49-10.jpeg","IMG_7CDC58C72E49-64.jpeg","IMG_7CDC58C72E49-72.jpeg"],"options":["Conversation, Contract and Commitment.","Customer, Card and Criteria.","Collaboration, Content and Confirmation.","Card, Commitment and Collaboration.","Card, Conversation and Confirmation."],"id":14,"answer":4,"category":"Теория","keyReferences":["Variant 1, №15"]},{"number":17,"text":"Scenario: After the plan for a tax-system upgrade is approved. the project manager issues a signed work order that releases funds so the database team can start its work package. Question: To which phase of the operating cycle does this activity belong:","sources":["IMG_7CDC58C72E49-2.jpeg","IMG_7CDC58C72E49-10.jpeg","IMG_7CDC58C72E49-64.jpeg","IMG_7CDC58C72E49-72.jpeg"],"options":["Work authorization and release.","Cost data collection and reporting.","Cost analysis.","Reporting to customer and management.","Variance at completion forecasting."],"id":15,"answer":0,"category":"Ситуации","keyReferences":["Variant 1, №17"]},{"number":18,"text":"Scenario: For a data-center project, BCWS is $450, BCWP is $400 and ACWP is $500 (in thousands). Question: What is the cost variance, and what does it indicate?","sources":["IMG_7CDC58C72E49-2.jpeg","IMG_7CDC58C72E49-64.jpeg"],"options":["+50; the project is on budget.","-100; the work cost more than budgeted.","+100; the work cost less than budgeted.","-100; the project is ahead of schedule.","-50; the project is behind schedule."],"id":16,"answer":1,"category":"Ситуации","keyReferences":["Variant 1, №18"]},{"number":19,"text":"Scenario: A cloud-migration project shows BCWP = 400 and ACWP = 500 (thousand dollars). Question: What is the CPI, and how should it be interpreted?","sources":["IMG_7CDC58C72E49-2.jpeg","IMG_7CDC58C72E49-3.jpeg","IMG_7CDC58C72E49-64.jpeg","IMG_7CDC58C72E49-65.jpeg"],"options":["1.25; work is faster than planned.","0.8; work is costing more than planned.","0.8; work is slower than planned.","1.0; cost performance is perfect.","1.25; work is costing less than planned."],"id":17,"answer":1,"category":"Ситуации","keyReferences":["Variant 1, №19"]},{"number":20,"text":"Scenario: An HR system project has a budget at completion of $1,000 thousand and a current CPI of 0.8. Question: What is the estimate at completion if this efficiency continues?","sources":["IMG_7CDC58C72E49-3.jpeg","IMG_7CDC58C72E49-65.jpeg"],"options":["$1.000 thousand.","S800 thousand.","$1.200 thousand","$1,250 thousand","$1,080 thousand."],"id":18,"answer":3,"category":"Ситуации","keyReferences":["Variant 1, №20"]},{"number":21,"text":"Scenario: Two weeks into a new digitization team, members argue about the approach and two senior developers openly compete to lead technical decisions. Onestion: Which stage of group development is the team in?","sources":["IMG_7CDC58C72E49-3.jpeg","IMG_7CDC58C72E49-65.jpeg"],"options":["Norming.","Adjouming,","Storming.","Performing.","Forming."],"id":19,"answer":2,"category":"Ситуации","keyReferences":["Variant 1, №21"]},{"number":22,"text":"Scenario: A procurement specialist at a ministry is expected to finish a tender report and, on the same afternoon, to sit on an interview panel in another building. Doing one makes the other impossible. Question: What is this situation called?","sources":["IMG_7CDC58C72E49-3.jpeg","IMG_7CDC58C72E49-65.jpeg"],"options":["Role conflict.","Punctuated equilibrium.","Storming.","Group cohesiveness.","Groupthink."],"id":20,"answer":0,"category":"Ситуации","keyReferences":["Variant 1, №22"]},{"number":23,"text":"Scenario: At an IT integrator in Almaty, management rates its engineers' technical skills very highly, yet most client projects finish late and over budget. Question: What does this situation most likely indicate?","sources":["IMG_7CDC58C72E49-3.jpeg","IMG_7CDC58C72E49-65.jpeg"],"options":["An ideal structure needing no change.","A market-wide fall in IT demand.","A shortage of technical certification","Budgets that were set too generously.","A structural problem in managing, projects."],"id":21,"answer":4,"category":"Ситуации"},{"number":24,"text":"Scenario: After a failed data migration at a bank, the project manager and the head of the infrastructure department each insist that the other caused the failure. Question: If trust continues to grow, what should happen next?","sources":["IMG_7CDC58C72E49-3.jpeg","IMG_7CDC58C72E49-65.jpeg"],"options":["Both managers readily admit responsibility.","Both managers deny that any problem exists.","The general manager replaces one of them.","Both escalate the issue to the customer.","Both begin to formally anticipate problems."],"id":22,"answer":0,"category":"Ситуации"},{"number":25,"text":"Scenario: The finance department of a state-owned utility can see at a glance what each department spends and keep it within agreed limits. Question: Which advantage of the traditional structure does this reflect?","sources":["IMG_7CDC58C72E49-3.jpeg","IMG_7CDC58C72E49-65.jpeg"],"options":["One person responsible for each project.","Easier budgeting and cost control.","Higher motivation and innovation.","Fast response to customer needs.","A single customer focal point."],"id":23,"answer":1,"category":"Ситуации","keyReferences":["Variant 1, №25"]},{"number":26,"text":"Scenario: A client of a software firm in Astana keeps asking who is in charge of her project; each department head says it is responsible only for its own part. Question: Which weakness of the traditional structure does this show?","sources":["IMG_7CDC58C72E49-3.jpeg","IMG_7CDC58C72E49-65.jpeg"],"options":["Excessive project authority.","Too many bosses per employee.","Too few specialists to share.","Weak technical control.","No customer focal point."],"id":24,"answer":4,"category":"Ситуации","keyReferences":["Variant 1, №26"]},{"number":27,"text":"Scenario: Before creating any project manager positions, a company coordinates work between units through rules and procedures, planning processes, hierarchical referral and direct contact. Question: What are these coordination methods called?","sources":["IMG_7CDC58C72E49-3.jpeg","IMG_7CDC58C72E49-4.jpeg","IMG_7CDC58C72E49-65.jpeg","IMG_7CDC58C72E49-66.jpeg"],"options":["Integrating mechanisms.","Matrix role definitions.","Projectized authority lines.","Stages in the growth of trust.","Liaison department duties."],"id":25,"answer":0,"category":"Ситуации","keyReferences":["Variant 1, №27"]},{"number":28,"text":"Scenario: In a defense contractor’s projectized division, the program manager assigns all work and also conducts the merit reviews of team members. Question: Which advantage of this structure does this illustrate?","sources":["IMG_7CDC58C72E49-4.jpeg","IMG_7CDC58C72E49-66.jpeg"],"options":["Strong continuity in each discipline.","Better use of scarce specialists.","Lower cost through shared personnel..","Easier staff sharing between projects.","Full line authority over the project."],"id":26,"answer":4,"category":"Ситуации","keyReferences":["Variant 1, №28"]},{"number":29,"text":"Scenario: A fintech company in Astana has complex products with short life cycles as its primary output. Question: Which organizational form is most worth considering?","sources":["IMG_7CDC58C72E49-4.jpeg","IMG_7CDC58C72E49-8.jpeg","IMG_7CDC58C72E49-66.jpeg","IMG_7CDC58C72E49-70.jpeg"],"options":["A pure functional organization.","Departmental project leaders.","Liaison departments only.","A matrix organization.","Integrating mechanisms only."],"id":27,"answer":3,"category":"Ситуации","keyReferences":["Variant 1, №29"]},{"number":30,"text":"Scenario: An akimat is building a standard two-storey school from a design thar has already been used for dozens of schools. Every construction step can be specified before work starts. Question: Which type of process best fits this project?","sources":["IMG_7CDC58C72E49-4.jpeg","IMG_7CDC58C72E49-8.jpeg","IMG_7CDC58C72E49-9.jpeg","IMG_7CDC58C72E49-66.jpeg","IMG_7CDC58C72E49-70.jpeg","IMG_7CDC58C72E49-71.jpeg"],"options":["An experimental process with frequent pivots.","An empirical process refined in each cycle.","An iterative process driven by user feedback.","An incremental process with emerging scope.","A defined process with steps set in advance."],"id":28,"answer":4,"category":"Ситуации","keyReferences":["Variant 1, №30"]},{"number":31,"text":"Scenario: An agile team at a state agency has a fixed budget of 100 million tenge and a fixed six-month deadline. Halfway through, it is clear that not every requested feature will fit. Question: Following the agile triangle, what should be adjusted?","sources":["IMG_7CDC58C72E49-4.jpeg","IMG_7CDC58C72E49-8.jpeg","IMG_7CDC58C72E49-9.jpeg","IMG_7CDC58C72E49-66.jpeg","IMG_7CDC58C72E49-70.jpeg","IMG_7CDC58C72E49-71.jpeg"],"options":["The scope delivered within the fixed cost and time.","The quality, so that scope, cost and time stay fixed.","The deadline, so that full scope fits the budget","The budget, so that full scope meets the deadline.","Both budget and deadline, while scope stays frozen."],"id":29,"answer":0,"category":"Ситуации","keyReferences":["Variant 1, №31"]},{"number":32,"text":"Scenario: A sponsor asks how the e-procurement projeet is going. The project manager reports that 80% of planned tasks are complete, but nothing can yet be demonstrated to users. Question: Which agile principle shows the weakness of this progress report?","sources":["IMG_7CDC58C72E49-4.jpeg","IMG_7CDC58C72E49-8.jpeg","IMG_7CDC58C72E49-9.jpeg","IMG_7CDC58C72E49-66.jpeg","IMG_7CDC58C72E49-70.jpeg","IMG_7CDC58C72E49-71.jpeg"],"options":["Business people and developers work together daily.","Working software is the main measure of progress.","The team reflects at regular intervals to improve.","Requirements changes are welcome even late on.","Simplicity maximizes the amount of work not done."],"id":30,"answer":1,"category":"Ситуации","keyReferences":["Variant 1, №32"]},{"number":33,"text":"Scenario: Before writing the code that calculates property tax. developers on an XP team first write automated checks that the code must pass. Question: Which XP practice is the team using?","sources":["IMG_7CDC58C72E49-4.jpeg","IMG_7CDC58C72E49-8.jpeg","IMG_7CDC58C72E49-9.jpeg","IMG_7CDC58C72E49-66.jpeg","IMG_7CDC58C72E49-70.jpeg","IMG_7CDC58C72E49-71.jpeg"],"options":["Refactoring.","Pair programming.","Customer tests.","Test-driven development.","Collective code ownership."],"id":31,"answer":3,"category":"Ситуации","keyReferences":["Variant 1, №33"]},{"number":34,"text":"Scenario: Developers at a bank in Almaty are each assigned to three projects at once and lose time every time they move from one to another. Question: Which Lean waste does this describe?","sources":["IMG_7CDC58C72E49-4.jpeg","IMG_7CDC58C72E49-8.jpeg","IMG_7CDC58C72E49-9.jpeg","IMG_7CDC58C72E49-66.jpeg","IMG_7CDC58C72E49-70.jpeg","IMG_7CDC58C72E49-71.jpeg"],"options":["Motion.","Extra processes.","Task switching.","Partially done work.","Defects."],"id":32,"answer":2,"category":"Ситуации","keyReferences":["Variant 1, №34"]},{"number":35,"text":"Scenario: A project leader at an Astana startup lets the developers choose the technical steps and tools, trusting their expertise rather than dictating the approach. Question: Which Lean core concept does this reflect?","sources":["IMG_7CDC58C72E49-4.jpeg","IMG_7CDC58C72E49-9.jpeg","IMG_7CDC58C72E49-66.jpeg","IMG_7CDC58C72E49-71.jpeg"],"options":["Optimize the whole.","Defer decisions.","Deliver fast.","Amplify learning.","Empower the team."],"id":33,"answer":4,"category":"Ситуации","keyReferences":["Variant 1, №35"]},{"number":36,"text":"Scenario: During an iteration, a depaty director keeps pulling developers into unplanned meetings. The agile leader asks him to route requests through her instead. Question: Which servant leader duty is she performing?","sources":["IMG_7CDC58C72E49-5.jpeg","IMG_7CDC58C72E49-67.jpeg"],"options":["Carrying food and water.","Re-communicating the project vision.","Practicing transparency.","Shielding the team from interruptions.","Recognizing confliet as a positive step."],"id":34,"answer":3,"category":"Ситуации","keyReferences":["Variant 1, №36"]},{"number":37,"text":"Scenario: A digital team at the Shymkent akimat decides which features to build next only affer observing how citizens actually used the previous release of its service portal, rather than relying on a long upfront forecast. Question: Which foundation of Scrum does this behavior reflect most directly?","sources":["IMG_7CDC58C72E49-5.jpeg","IMG_7CDC58C72E49-67.jpeg"],"options":["Critical path analysis.","Waterfall phase gating.","Empiricism.","Lean thinking.","Predictive planning."],"id":35,"answer":2,"category":"Ситуации","keyReferences":["Variant 1, №37"]},{"number":38,"text":"Scenario: An IT manager at a bank proposes creating a testing sub- team inside the Scrum Team, with its own lead who reports to a senior developer. Question: Which response is consistent with Scrum?","sources":["IMG_7CDC58C72E49-5.jpeg","IMG_7CDC58C72E49-67.jpeg"],"options":["Accept it, since testers need a separate lead to stay focused.","Accept it, since cross-functional teams need specialized sub-units.","Accept it, if the Scrum Master approves the reporting line.","Reject it, since a Scrum Team has no sub-teams or hierarchies.","Reject it, since testing should be done by the Product Owner."],"id":36,"answer":3,"category":"Ситуации","keyReferences":["Variant 1, №38"]},{"number":39,"text":"Scenario: A ministry assigns a steering committee of five deputy heads to act jointly as the Product Owner for a new licensing system. Question: What is the main problem with this arrangement from a Scrum perspective?","sources":["IMG_7CDC58C72E49-5.jpeg","IMG_7CDC58C72E49-67.jpeg"],"options":["The Product Owner must be a member of the Developers.","The Product Owner must be one person, not a committee.","Deputy heads lack the technical skills to size items.","A committee cannot attend the Daily Scrum every day.","The committee should include the Scrum Master as chair."],"id":37,"answer":1,"category":"Ситуации","keyReferences":["Variant 1, №39"]},{"number":40,"text":"Scenario: The Scrum Master of a team at a telecom company announces: “I will decide who takes which task each morning so that you work efficiently.” Question: What is the main issue with this approach?","sources":["IMG_7CDC58C72E49-5.jpeg","IMG_7CDC58C72E49-67.jpeg"],"options":["The Scrum Master should coach self-management, not assign work.","Task assignment is the Product Owner's job, not the Scrum Master's.","The Scrum Master should assign tasks only during Sprint Planning.","This is acceptable while the Developers are new to Scrum.","Task assignment should be done by the most senior Developer."],"id":38,"answer":0,"category":"Ситуации","keyReferences":["Variant 1, №40"]},{"number":41,"text":"Scenario: A team in Almaty proposes six-week Sprints because its features are large. Question: What does Scrum say about this proposal?","sources":["IMG_7CDC58C72E49-5.jpeg","IMG_7CDC58C72E49-67.jpeg"],"options":["Six weeks is allowed if stakeholders agree.","The Product Owner picks a new length each Sprint.","Sprints must be exactly two weeks long.","Sprint length may vary with feature size.","Sprints must be fixed at one month or less."],"id":39,"answer":4,"category":"Ситуации","keyReferences":["Variant 1, №41"]},{"number":42,"text":"Scenario: The Daily Scrum at a telecom company regularly takes 45 minutes and consists of status reports to the department head. Question: Which change best aligns it with Scrum?","sources":["IMG_7CDC58C72E49-5.jpeg","IMG_7CDC58C72E49-67.jpeg"],"options":["Keep 45 minutes but limit it to three questions.","Cut it to 30 minutes and email status to managers.","Keep it to 15 minutes, focused on the Sprint Goal.","Move it to once a week to save working time.","Let the department head chair it for discipline."],"id":40,"answer":2,"category":"Ситуации","keyReferences":["Variant 1, №42"]},{"number":43,"text":"Scenario: At the end of a Sprint, the team and stakeholders from the Ministry of Health try the new features, discuss upcoming regulatory changes and agree to reorder the Product Backlog. Question: Which Scrum event is taking place","sources":["IMG_7CDC58C72E49-5.jpeg","IMG_7CDC58C72E49-6.jpeg","IMG_7CDC58C72E49-67.jpeg","IMG_7CDC58C72E49-68.jpeg"],"options":["Backlog refinement.","Sprint Retrospective.","Sprint Planning.","Sprint Review.","Daily Scrum."],"id":41,"answer":3,"category":"Ситуации","keyReferences":["Variant 1, №43"]},{"number":45,"text":"Scenario: An analyst prepared one-page persona summaries for a clinic appointment app. After a month of interviews with patients, the team wants a richer picture of each persona. Question: What is the most appropriate next step?","sources":["IMG_7CDC58C72E49-6.jpeg","IMG_7CDC58C72E49-68.jpeg"],"options":["Keep the short versions, since long ones suit only waterfall projects.","Average the interview data into one generic persona.","Convert each persona directly into an acceptance test.","Replace the personas with a plain list of system actors.","Expand the personas into the long template using the new research."],"id":42,"answer":4,"category":"Теория","keyReferences":["Variant 1, №45"]},{"number":47,"text":"Scenario: A backlog item for a tax portal reads: “As a taxpayer, I need to download my income certificate.” Question: Which component of the common user story format is missing?","sources":["IMG_7CDC58C72E49-6.jpeg","IMG_7CDC58C72E49-68.jpeg"],"options":["The effort estimate for the story.","The user role or persona (WHO).","The action or feature needed (WHAT).","The benefit or value to the user (WHY).","The acceptance criteria that confirm the story."],"id":43,"answer":3,"category":"Ситуации","keyReferences":["Variant 1, №47"]},{"number":48,"text":"Scenario: For the story 'As a borrower, I need to see my monthly loan payment so that I can plan my budget, the product owner adds: shows the amount in tenge; updates after each payment; visible on the home screen. Question: What role do these added statements play?","sources":["IMG_7CDC58C72E49-6.jpeg","IMG_7CDC58C72E49-7.jpeg","IMG_7CDC58C72E49-68.jpeg","IMG_7CDC58C72E49-69.jpeg"],"options":["They fix the order of stories in the next release.","They define the story's boundaries for verification.","They describe the borrower persona's motivations and traits.","They replace the conversation between team and users.","They give the team's effort estimate for the story."],"id":44,"answer":1,"category":"Ситуации","keyReferences":["Variant 1, №48"]},{"number":49,"text":"Scenario: A ministry replaced 200-page specifications with user stories and now releases a small piece of its licensing service every two weeks. Question: What is the main benefit of this change?","sources":["IMG_7CDC58C72E49-6.jpeg","IMG_7CDC58C72E49-7.jpeg","IMG_7CDC58C72E49-68.jpeg","IMG_7CDC58C72E49-69.jpeg"],"options":["Stories remove the need to refine the backlog.","Stories make long-term estimates exact.","Small testable slices give fast delivery and feedback.","Stories let the team skip stakeholder talks.","Stories hold complete specs, so fewer questions arise."],"id":45,"answer":2,"category":"Ситуации","keyReferences":["Variant 1, №49"]},{"number":50,"text":"Scenario: The backlog of an e-government portal has grown to 900 user stories, many of them outdated or duplicated, and planning meetings take hours. Question: Which action best addresses this limitation of user stories?","sources":["IMG_7CDC58C72E49-6.jpeg","IMG_7CDC58C72E49-7.jpeg","IMG_7CDC58C72E49-68.jpeg","IMG_7CDC58C72E49-69.jpeg"],"options":["Add more developers to finish all 900 stories.","Stop writing acceptance criteria to save time.","Refine and reprioritize the backlog regularly.","Convert every story into a detailed specification.","Freeze the backlog until the end of the project."],"id":46,"answer":2,"category":"Ситуации","keyReferences":["Variant 1, №50"]},{"number":10,"text":"Which Scrum value is needed to take on difficult problems and do what is right, even when it is uncomfortable?","sources":["IMG_7CDC58C72E49-10.jpeg","IMG_7CDC58C72E49-72.jpeg"],"options":["Courage.","Focus.","Openness.","Respect.","Commitment."],"id":51,"answer":0,"category":"Теория","keyReferences":["Variant 1, №10"]},{"number":16,"text":"Scenario: An e-government portal project in Astana had accurate initial estimates, but nobody updated the forecast of what the unfinished modules would cost. In month 10 the team discovered the remaining work needed twice the money left. Question: Which requirement of an effective control system was missing?","sources":["IMG_7CDC58C72E49-10.jpeg","IMG_7CDC58C72E49-72.jpeg"],"options":["Thorough planning of the work to be performed.","Periodic re-estimation of cost to complete.","Good initial estimating of time, labor and costs.","A disciplined budget and authorization of expenditures.","Clear communication of the scope of required tasks."],"id":52,"answer":1,"category":"Ситуации","keyReferences":["Variant 1, №16"]},{"number":4,"text":"Which term describes the power, often given by position, to make final decisions?","sources":["IMG_7CDC58C72E49-11.jpeg","IMG_7CDC58C72E49-73.jpeg"],"options":["Hierarchical referral.","Accountability.","Direct contact.","Authority.","Responsibility."],"id":54,"answer":3,"category":"Теория","keyReferences":["Variant 1, №4"]},{"number":6,"text":"In a matrix, who keeps the responsibility for technical excellence on the project?","sources":["IMG_7CDC58C72E49-12.jpeg","IMG_7CDC58C72E49-33.jpeg"],"options":["The project coordinators.","The general manager.","The project manager.","The director of project management.","The functional departments."],"id":55,"answer":4,"category":"Теория","keyReferences":["Variant 3, №6"]},{"number":7,"text":"What does the Agile Manifesto say about the items on the right side of its four values?","sources":["IMG_7CDC58C72E49-12.jpeg","IMG_7CDC58C72E49-33.jpeg"],"options":["They have no value and should be removed from projects.","They matter only in large government projects.","They are valued equally with the items on the left.","They have value, but the left items are valued more.","They are valued more than the items on the left."],"id":56,"answer":3,"category":"Теория","keyReferences":["Variant 3, №7"]},{"number":8,"text":"Which Kanban principle restricts how many items the team handles at once, making bottlenecks easier to see?","sources":["IMG_7CDC58C72E49-12.jpeg","IMG_7CDC58C72E49-33.jpeg"],"options":["Limit WIP.","Improve collaboratively.","Manage flow.","Make process policies explicit.","Visualize the workflow."],"id":57,"answer":0,"category":"Теория","keyReferences":["Variant 3, №8"]},{"number":9,"text":"Which method is centered on eight principles such as “focus on the business need” and “never compromise quality”?","sources":["IMG_7CDC58C72E49-12.jpeg","IMG_7CDC58C72E49-33.jpeg"],"options":["DSDM.","Crystal.","FDD.","XP.","Kanban."],"id":58,"answer":0,"category":"Теория","keyReferences":["Variant 3, №9"]},{"number":10,"text":"Which Scrum value means keeping primary attention on the work of the Sprint to make the best progress toward its goals?","sources":["IMG_7CDC58C72E49-12.jpeg","IMG_7CDC58C72E49-13.jpeg","IMG_7CDC58C72E49-33.jpeg","IMG_7CDC58C72E49-34.jpeg"],"options":["Commitment.","Courage.","Transparency.","Respect.","Focus."],"id":59,"answer":4,"category":"Теория","keyReferences":["Variant 3, №10"]},{"number":22,"text":"Scenario: An HR specialist at a bank in Almaty writes down the pattern of behavior attached to the position of release manager, regardless of who fills it. Question: Which concept is being described?","sources":["IMG_7CDC58C72E49-14.jpeg","IMG_7CDC58C72E49-36.jpeg"],"options":["A role set.","A norm of the group.","Group cohesiveness.","A role.","A status hierarchy."],"id":60,"answer":3,"category":"Ситуации","keyReferences":["Variant 3, №22"]},{"number":23,"text":"Scenario: On a ministry's e-government project, the testing group and the development group constantly blame each other for missed specifications and delivery dates. Question: Which conclusion is most appropriate for senior management?","sources":["IMG_7CDC58C72E49-14.jpeg","IMG_7CDC58C72E49-36.jpeg"],"options":["Delivery dates should be removed from the project plan.","The testing group should be disbanded and outsourced.","The organization may not be designed for project work.","Only the development group's leader should be replaced.","The testing group lacks the needed technical skills."],"id":61,"answer":2,"category":"Ситуации","keyReferences":["Variant 3, №23"]},{"number":24,"text":"Scenario: A project manager sees a growing integration problem, but both she and the head of the QA department tell every status meeting that “everything is fine”. Question: At which stage of trust are the two managers?","sources":["IMG_7CDC58C72E49-14.jpeg"],"options":["Blaming each other for the problem.","Admitting responsibility for it.","Denying that a problem exists.","Anticipating problems together.","Working it out face-to-face."],"id":62,"answer":2,"category":"Ситуации","keyReferences":["Variant 3, №24"]},{"number":27,"text":"Scenario: Each functional unit of a bank places a representative on a group that jointly solves project problems; work is on time, but in conflicts members side with their home departments. Question: Which arrangement is this, and what is its key weakness?","sources":["IMG_7CDC58C72E49-15.jpeg","IMG_7CDC58C72E49-37.jpeg"],"options":["A strong matrix in which the PM dominates daily work.","A liaison department whose authority ends at the division.","A traditional structure with no customer focal point.","A pure project team with very high overhead costs.","A task force whose members stay loyal to their units."],"id":63,"answer":4,"category":"Ситуации","keyReferences":["Variant 3, №27"]},{"number":28,"text":"Scenario: A projectized team at an IT company keeps a database specialist on the project for months after her tasks are finished. Question: Why does this typically happen in such structures?","sources":["IMG_7CDC58C72E49-15.jpeg","IMG_7CDC58C72E49-37.jpeg"],"options":["The PM fears not getting her back later.","Contracts forbid moving staff between projects.","Merit reviews require full project tenure.","She reports to a line manager in another unit.","Functional managers refuse to take her back."],"id":64,"answer":0,"category":"Ситуации","keyReferences":["Variant 3, №28"]},{"number":29,"text":"Scenario: A company adopts a matrix structure but continues to reward staff only for meeting their functional department's goals. Question: Which implementation requirement is missing?","sources":["IMG_7CDC58C72E49-15.jpeg","IMG_7CDC58C72E49-37.jpeg"],"options":["A single reporting line.","A larger marketing budget.","Hierarchical referral.","Compatible reward systems.","Fully dedicated project staff."],"id":65,"answer":3,"category":"Ситуации","keyReferences":["Variant 3, №29"]},{"number":30,"text":"Scenario: A ministry's portfolio office is deciding which of its upcoming projects should be run with agil methods. Question: Which project characteristic most strongly favors an agile approach?","sources":["IMG_7CDC58C72E49-15.jpeg","IMG_7CDC58C72E49-37.jpeg"],"options":["A fixed scope fully signed off by the customer.","Low uncertainty and a stable technology base.","Knowledge work in a fast, complex setting.","Repeatable work with well-known physical steps.","Predictable tasks that follow a known sequence."],"id":66,"answer":2,"category":"Ситуации","keyReferences":["Variant 3, №30"]},{"number":31,"text":"Scenario: A sponsor tells the project manager: \"Every feature in the specification must be delivered. Estimate whatever time and money that takes.\" Question: Which planning model does this instruction reflect?","sources":["IMG_7CDC58C72E49-15.jpeg","IMG_7CDC58C72E49-37.jpeg","IMG_7CDC58C72E49-38.jpeg"],"options":["The agile triangle, with scope allowed to vary.","The traditional triangle, with scope fixed.","An empirical model driven by experimentation.","The inverted triangle, with cost and time fixed.","A model where only cost and quality are fixed."],"id":67,"answer":1,"category":"Ситуации","keyReferences":["Variant 3, №31"]},{"number":25,"text":"Scenario: The HR department of a ministry values that every employee has one and only one person to report to. Question: Which advantage of the traditional structure does this provide?","sources":["IMG_7CDC58C72E49-14.jpeg"],"options":["Good control over personnel.","Quick response to customers.","Strong horizontal communication.","Clear project accountability.","Simple cross-unit coordination."],"id":70,"answer":0,"category":"Ситуации","keyReferences":["Variant 3, №25"]},{"number":26,"text":"Scenario: At a traditionally organized bank, a decision on a new loan system needs sign-off from four departments, adding several weeks to the schedule. Question: Which disadvantage does this illustrate?","sources":["IMG_7CDC58C72E49-16.jpeg"],"options":["Specialists unable to share their knowledge.","Difficult budgeting and cost control.","Employees having more than one supervisor.","Complex coordination and slow approvals.","Weak technical control over the work."],"id":71,"answer":3,"category":"Ситуации","keyReferences":["Variant 3, №26"]},{"number":37,"text":"Scenario: At every Sprint Review, an e-government team in Astana identifies the same usability problems and records them in a report, but never changes the Product Backlog or its way of working. Question: How does Scrum characterize this situation?","sources":["IMG_7CDC58C72E49-17.jpeg","IMG_7CDC58C72E49-39.jpeg"],"options":["The team is applying empiricism correctly.","The team is applying lean thinking correctly.","Adaptation should wait until the product is released.","Inspection without adaptation is pointless.","Transparency without inspection is misleading."],"id":72,"answer":3,"category":"Ситуации","keyReferences":["Variant 3, №37"]},{"number":38,"text":"Scenario: In a newly formed Scrum Team at a logistics company, the department head insists on assigning daily tasks to each Developer and deciding how they should be done. Question: Which characteristic of a Scrum Team does this conflict with most directly?","sources":["IMG_7CDC58C72E49-17.jpeg","IMG_7CDC58C72E49-39.jpeg"],"options":["Transparency.","Self-management.","Lean thinking.","Cross-functionality.","Timeboxing."],"id":73,"answer":1,"category":"Ситуации","keyReferences":["Variant 3, №38"]},{"number":39,"text":"Scenario: A deputy akim wants a new feature moved to the top of the work list and tells the Developers directly to add it. Question: What is the appropriate way for him to get the Product Backlog changed?","sources":["IMG_7CDC58C72E49-17.jpeg","IMG_7CDC58C72E49-39.jpeg"],"options":["Raise it at the Daily Scrum so Developers can vote.","Ask the Developers to add it to the current Sprint.","Ask the Scrum Master to reorder the Product Backlog.","Add it directly, since senior officials outrank the team.","Convince the Product Owner to change the backlog."],"id":74,"answer":4,"category":"Ситуации","keyReferences":["Variant 3, №39"]},{"number":40,"text":"Scenario: In a team with one-month Sprints, the Sprint Review regularly runs for six hours, and the Daily Scrum often exceeds half an hour. Question: What should the Scrum Master ensure?","sources":["IMG_7CDC58C72E49-17.jpeg","IMG_7CDC58C72E49-39.jpeg"],"options":["That timeboxes are extended when stakeholders need it.","That events take place and stay within the timebox.","That the Product Owner decides how long events last.","That long events are split into separate presentations.","That timeboxes are applied only to the Daily Scrum."],"id":75,"answer":1,"category":"Ситуации","keyReferences":["Variant 3, №40"]},{"number":41,"text":"Scenario: Midway through a Sprint, a deputy minister asks the team to swap half of its items for unrelated urgent work. The change would make the still-valid Sprint Goal unreachable. Question: What is the most appropriate response?","sources":["IMG_7CDC58C72E49-17.jpeg"],"options":["Extend the Sprint by two weeks to fit in the new work.","Swap the items, since senior officials can change Sprint scope.","Place the request in the Product Backlog for a later Sprint.","Accept the work and reduce testing to fit everything in.","Let the Scrum Master cancel the Sprint and start a new one."],"id":76,"answer":2,"category":"Ситуации","keyReferences":["Variant 3, №41"]},{"number":8,"text":"Scenario: A QA engineer at a bank needs a basis for regression and exploratory tests for the story “Block a lost card”. Question: Which source should she rely on first?","sources":["IMG_7CDC58C72E49-18.jpeg"],"options":["The persona's long template.","The story/'s acceptance criteria.","The sprint burndown chart.","The story's title on the card.","The product vision statement."],"id":77,"answer":1,"category":"Ситуации","keyReferences":["Variant 3, №48","Variant 2, №48"]},{"number":49,"text":"Scenario: An analyst lists activities on a digital-services project that will change once the team starts working with user stories. Question: Which activity is directly affected by user stories?","sources":["IMG_7CDC58C72E49-18.jpeg","IMG_7CDC58C72E49-41.jpeg"],"options":["Sprint retrospective.","Pair programming.","Critical path calculation.","Product roadmap.","Earned value analysis."],"id":78,"answer":3,"category":"Ситуации","keyReferences":["Variant 3, №49"]},{"number":50,"text":"Scenario: In a student portal backlog, most stories look like 'As a student, I need a PDF export button.! The 'so that' part is usually left out. Question: Which limitation of user stories does this reflect?","sources":["IMG_7CDC58C72E49-18.jpeg","IMG_7CDC58C72E49-19.jpeg","IMG_7CDC58C72E49-41.jpeg","IMG_7CDC58C72E49-42.jpeg"],"options":["Giving too much detail on the user role.","Writing too few stories to fill the backlog.","Focusing on the WHAT while overlooking the WHY.","Making stories too dependent on each other.","Relying too heavily on persona differentiators."],"id":79,"answer":2,"category":"Ситуации","keyReferences":["Variant 3, №50"]},{"number":32,"text":"Scenario: A team reviews its backlog and drops six rarely used features, delivering the same business value with much less effort. Question: Which agile principle does this decision apply?","sources":["IMG_7CDC58C72E49-19.jpeg"],"options":["Early and continuous delivery of value.","Self-organizing teams creating designs.","Daily collaboration with business people.","Continuous attention to technical excellence.","Simplicity, maximizing the work not done."],"id":80,"answer":4,"category":"Ситуации","keyReferences":["Variant 3, №32"]},{"number":33,"text":"Scenario: A developer restructures a tangled module to make it easier to read. Users see no change in behavior and no new functions are added. Question: Which XP practice is being applied?","sources":["IMG_7CDC58C72E49-19.jpeg","IMG_7CDC58C72E49-38.jpeg"],"options":["Simple design.","Test-driven development.","Metaphor.","Continuous integration.","Refactoring."],"id":81,"answer":4,"category":"Ситуации","keyReferences":["Variant 3, №33"]},{"number":34,"text":"Scenario: Every small change on an e-goverment project needs four signatures, and the team produces weekly reports that nobody reads. Question: Which Lean waste does this represent?","sources":["IMG_7CDC58C72E49-19.jpeg","IMG_7CDC58C72E49-38.jpeg"],"options":["Task switching.","Extra processes.","Extra features.","Defects.","Partially done work."],"id":82,"answer":1,"category":"Ситуации","keyReferences":["Variant 3, №34"]},{"number":35,"text":"Scenario: The development unit of a ministry doubled its own speed, but overall delivery to citizens slowed because testing and deployment could not keep up. Question: Which Lean core concept was neglected?","sources":["IMG_7CDC58C72E49-19.jpeg","IMG_7CDC58C72E49-38.jpeg"],"options":["Amplify learning.","Build quality in.","Optimize the whole.","Empower the team.","Defer decisions."],"id":83,"answer":2,"category":"Ситуации","keyReferences":["Variant 3, №35"]},{"number":36,"text":"Scenario: Two candidates for team leader describe their style. One focuses on tasks, control and speed; the other on people, purpose and empowerment. Question: How are these two styles best classified?","sources":["IMG_7CDC58C72E49-19.jpeg","IMG_7CDC58C72E49-38.jpeg"],"options":["Both describe servant leadership in agile teams.","The first is agile; the second is a defined process.","The first is management; the second is leadership.","Both describe traditional command and control.","The first is leadership; the second is management."],"id":84,"answer":2,"category":"Ситуации","keyReferences":["Variant 3, №36"]},{"number":42,"text":"Scenario: Developers at a bank want to drop the familiar “three questions” and instead walk the board item by item, focusing on the Sprint Goal. Their Scrum Master is unsure. Question: How does Scrum view this change?","sources":["IMG_7CDC58C72E49-20.jpeg"],"options":["It is allowed only for Sprints shorter than two weeks.","It is allowed; Developers choose the structure and techniques.","It is not allowed; the board is reviewed only at the Sprint Review.","It is allowed only if the Product Owner approves it.","It is not allowed; the three questions are mandatory."],"id":85,"answer":1,"category":"Ситуации","keyReferences":["Variant 3, №42"]},{"number":43,"text":"Scenario: A team at an IT park company turns its Sprint Review into a 30-minute slideshow with no discussion, and stakeholders leave without giving any input. Question: What is the best advice for this team?","sources":["IMG_7CDC58C72E49-20.jpeg","IMG_7CDC58C72E49-40.jpeg"],"options":["Replace it with a written report sent after the Sprint.","Move the discussion of next steps to the Retrospective.","Keep it short, since the review is mainly a formal demo.","Skip stakeholders and present only to the Product Owner.","Make it a working session to decide what to do next."],"id":86,"answer":4,"category":"Ситуации","keyReferences":["Variant 3, №43"]},{"number":44,"text":"Scenario: A university portal team has described five personas: applicant, first-year student, lecturer, dean's office clerk and parent. The budget covers features for only some of them in the first release. Question: What should the team do with these personas?","sources":["IMG_7CDC58C72E49-20.jpeg","IMG_7CDC58C72E49-40.jpeg"],"options":["Drop any persona that has no record in the student database.","Treat all five as equally important by default.","Let developers vote for the persona they find most interesting.","Merge them into one average user to simplify the design.","Rank them to find those who gain the most benefit."],"id":87,"answer":4,"category":"Ситуации","keyReferences":["Variant 3, №44"]},{"number":45,"text":"Scenario: In workshops for a ministry's document-flow system, each department head insists the system should work exactly the way he or she personally works. Question: Which benefit of personas helps the analyst deal with this situation?","sources":["IMG_7CDC58C72E49-20.jpeg","IMG_7CDC58C72E49-40.jpeg"],"options":["Personas stop stakeholders projecting their own biases.","Personas remove the need for workshops with departments.","Personas give department heads final say on priorities.","Personas fix the scope so that no changes are allowed.","Personas replace the product owner in decision making."],"id":88,"answer":0,"category":"Ситуации","keyReferences":["Variant 3, №45"]},{"number":46,"text":"Scenario: Personas for a university distance-learning portal were written in 2020, when most students studied from home. Today most classes are held on campus. Question: What should the analyst do?","sources":["IMG_7CDC58C72E49-20.jpeg","IMG_7CDC58C72E49-40.jpeg","IMG_7CDC58C72E49-41.jpeg"],"options":["Review and update the personas.","Merge all the personas into a single average student.","Delete the personas and rely only on role descriptions.","Turn the old personas into acceptance criteria.","Keep the personas, since they are fictional anyway."],"id":89,"answer":0,"category":"Ситуации","keyReferences":["Variant 3, №46"]},{"number":5,"text":"Which three common varieties can a matrix structure take?","sources":["IMG_7CDC58C72E49-21.jpeg","IMG_7CDC58C72E49-51.jpeg"],"options":["Strong, weak, or balanced.","Departmental, divisional, or liaison.","Pure, functional, or projectized.","Simple, complex, or hybrid.","Line, staff, or line-staff."],"id":90,"answer":0,"category":"Теория","keyReferences":["Variant 5, №5"]},{"number":6,"text":"Why is project engineering separated from project management in a matrix?","sources":["IMG_7CDC58C72E49-21.jpeg","IMG_7CDC58C72E49-51.jpeg"],"options":["So all conflicts go to the general manager.","So costs can be shared among several projects.","So a liaison department can handle design changes.","To keep technical direction with engineering.","So the project manager can conduct merit reviews."],"id":91,"answer":3,"category":"Теория","keyReferences":["Variant 5, №6"]},{"number":7,"text":"Under the Agile Manifesto, why should effort go into responding to change rather than following a plan?","sources":["IMG_7CDC58C72E49-21.jpeg","IMG_7CDC58C72E49-51.jpeg"],"options":["Plans have no value once development begins.","Changes are rare in knowledge worker projects.","Detailed plans slow down contract negotiation.","Initial plans were made when least was known.","Plans must be fixed before scope can vary."],"id":92,"answer":3,"category":"Теория","keyReferences":["Variant 5, №7"]},{"number":8,"text":"In Kanban, what is the main purpose of limiting work in progress?","sources":["IMG_7CDC58C72E49-21.jpeg","IMG_7CDC58C72E49-51.jpeg"],"options":["To identify issues and minimize waste.","To keep every team member fully busy.","To fix the scope before each iteration.","To replace the need for a task board.","To make the team deliver every two weeks."],"id":93,"answer":0,"category":"Теория","keyReferences":["Variant 5, №8"]},{"number":9,"text":"Which practice is part of the set of good practices recommended by Feature-Driven Development?","sources":["IMG_7CDC58C72E49-21.jpeg","IMG_7CDC58C72E49-51.jpeg"],"options":["Individual code ownership.","Test-driven development.","Collective code ownership.","Pair programming.","Limiting work in progress."],"id":94,"answer":0,"category":"Теория","keyReferences":["Variant 5, №9"]},{"number":10,"text":"Which list correctly names the five Scrum values?","sources":["IMG_7CDC58C72E49-21.jpeg","IMG_7CDC58C72E49-51.jpeg"],"options":["Commitment, focus, transparency, respect and empiricism.","Commitment, openness, adaptation, trust and simplicity.","Commitment, focus, openness, respect and courage.","Transparency, inspection, adaptation, respect and courage.","Courage, focus, inspection, respect and self-management."],"id":95,"answer":2,"category":"Теория","keyReferences":["Variant 5, №10"]},{"number":13,"text":"What does the short persona template offer compared with the long template?","sources":["IMG_7CDC58C72E49-22.jpeg","IMG_7CDC58C72E49-29.jpeg","IMG_7CDC58C72E49-52.jpeg","IMG_7CDC58C72E49-59.jpeg","IMG_7CDC58C72E49-74.jpeg"],"options":["A set of acceptance criteria for each story.","An in-depth story of the user's typical day.","A full list of the user's wants and wishes.","A ranked list of features for the release.","A one-page quick view of key information."],"id":96,"answer":4,"category":"Теория","keyReferences":["Variant 5, №13"]},{"number":14,"text":"Which INVEST criterion is met when a story explains why the customer will benefit from it?","sources":["IMG_7CDC58C72E49-22.jpeg","IMG_7CDC58C72E49-29.jpeg","IMG_7CDC58C72E49-52.jpeg","IMG_7CDC58C72E49-59.jpeg","IMG_7CDC58C72E49-74.jpeg"],"options":["Testable.","Valuable","Independent.","Estimable.","Negotiable."],"id":97,"answer":1,"category":"Теория","keyReferences":["Variant 5, №14"]},{"number":15,"text":"What does the Card in the 3Cs mainly contain?","sources":["IMG_7CDC58C72E49-22.jpeg","IMG_7CDC58C72E49-23.jpeg","IMG_7CDC58C72E49-29.jpeg","IMG_7CDC58C72E49-30.jpeg","IMG_7CDC58C72E49-52.jpeg","IMG_7CDC58C72E49-53.jpeg","IMG_7CDC58C72E49-59.jpeg","IMG_7CDC58C72E49-60.jpeg","IMG_7CDC58C72E49-74.jpeg"],"options":["The effort estimate and the deadline.","Notes from every team discussion.","A brief story and an optional title.","The acceptance tests for the feature.","The full specification of the feature."],"id":98,"answer":2,"category":"Теория","keyReferences":["Variant 5, №15"]},{"number":27,"text":"Scenaric: A new PMO head in Almaty claims that once the project plan is approved, planning has no further connection to how costs are authorized, collected, analyzed and reported. Question: Which statement best corrects this view?","sources":["IMG_7CDC58C72E49-23.jpeg","IMG_7CDC58C72E49-53.jpeg","IMG_7CDC58C72E49-75.jpeg"],"options":["Planning is repeated only when the customer requests it.","Cost control is a complete system independent of planning.","Planning is the last phase and follows customer reporting.","The operating cycle fully replaces planning after approval.","Planning and operations form one closed system."],"id":99,"answer":4,"category":"Теория","keyReferences":["Variant 5, №17"]},{"number":18,"text":"Scenario: A software team measures in hours: BCWS = 1,200, BCWP = 1,000, ACWP = 1,100. Question: Which statement about the variances is correct?","sources":["IMG_7CDC58C72E49-23.jpeg","IMG_7CDC58C72E49-53.jpeg","IMG_7CDC58C72E49-75.jpeg"],"options":["CV = -100 and SV = +200.","CV = +200 and SV = +100.","CV = - 100 and SV = - 200.","CV = +100 and SV = -200.","CV =-200 and SV = -100."],"id":100,"answer":2,"category":"Ситуации","keyReferences":["Variant 5, №18"]},{"number":21,"text":"Scenario: A task force with an eight-week deadline spent the first four weeks discussing options with little progress. At the midpoint, realizing time was running out, it changed course and worked intensively to finish. Question: Which model best explains this pattern?","sources":["IMG_7CDC58C72E49-24.jpeg","IMG_7CDC58C72E49-54.jpeg","IMG_7CDC58C72E49-76.jpeg"],"options":["The groupthink model.","The closed-system cost model.","The punctuated equilibrium model.","The storming stage of development.","The five-stage maturity model."],"id":101,"answer":2,"category":"Ситуации","keyReferences":["Variant 5, №21"]},{"number":22,"text":"Scenario: A director notices that several team leaders face simultaneous demands where meeting one demand rules out the others, and she wants to know why management should care. Question: What is the main organizational consequence of such role conflict?","sources":["IMG_7CDC58C72E49-24.jpeg","IMG_7CDC58C72E49-54.jpeg","IMG_7CDC58C72E49-76.jpeg"],"options":["Faster movement to the performing stage.","A shift from formal to informal groups.","Slower movement from forming to storming.","Higher overhead rates in every department.","Ineffective performance by people and groups."],"id":102,"answer":4,"category":"Ситуации"},{"number":23,"text":"Scenario: Staff at a telecom company in Astana are highly committed to project work, yet how well specifications are met varies greatly between projects. The CEO asks a consultant to design “the one ideal structure that will suit us forever”. Question: Which response reflects the soundest organizational thinking?","sources":["IMG_7CDC58C72E49-24.jpeg","IMG_7CDC58C72E49-54.jpeg"],"options":["Review it, accepting no structure is ideal.","Adopt a pure functional structure, ideal for all firms.","Keep the current structure, since commitment is high.","Loosen the specifications so the variation disappears.","Adopt a matrix, since it is ideal for every company."],"id":103,"answer":0,"category":"Ситуации"},{"number":24,"text":"Scenario: A new PMO director at a ministry wants project and functional managers to anticipate problems jointly from next week, although they currently deny that problems exist. Question: What is the most realistic expectation?","sources":["IMG_7CDC58C72E49-24.jpeg","IMG_7CDC58C72E49-25.jpeg","IMG_7CDC58C72E49-54.jpeg","IMG_7CDC58C72E49-55.jpeg"],"options":["A policy memo lets managers skip straight to anticipation.","Denial is actually the final, most mature stage of trust.","Anticipation normally comes before admitting responsibility.","Several intermediate stages of trust must come first.","Trust develops only when the PM has full line authority."],"id":104,"answer":3,"category":"Ситуации","keyReferences":["Variant 5, №24"]},{"number":26,"text":"Scenario: A ministry asks why its functional structure produces \"committee solutions\" for projects and why nobody can be pinpointed when a project fails. Question: What is the best explanation?","sources":["IMG_7CDC58C72E49-25.jpeg","IMG_7CDC58C72E49-55.jpeg","IMG_7CDC58C72E49-76.jpeg"],"options":["Specialists are grouped by discipline to share work.","Vertical communication channels are too weak.","The project manager holds too much line authority.","No one holds formal authority over the total project.","Each employee reports to more than one functional manager."],"id":105,"answer":3,"category":"Ситуации","keyReferences":["Variant 5, №26"]},{"number":27,"text":"Scenario: A company finds that project coordinators placed inside functional departments keep putting functional work ahead of their projects. Question: Which principle should guide the next step in organizing project work?","sources":["IMG_7CDC58C72E49-25.jpeg","IMG_7CDC58C72E49-55.jpeg","IMG_7CDC58C72E49-76.jpeg","IMG_7CDC58C72E49-77.jpeg"],"options":["Give project control to people loyal to the project.","Keep project leaders within each functional department.","Rely only on better rules and planning procedures.","Let liaison staff coordinate within one division.","Let functional managers run project merit reviews."],"id":106,"answer":0,"category":"Ситуации","keyReferences":["Variant 5, №27"]},{"number":28,"text":"Scenario: A holding company is considering a projectized structure for one of its subsidiaries. Question: Under which condition does such a structure give stable work and minimal conflict?","sources":["IMG_7CDC58C72E49-25.jpeg","IMG_7CDC58C72E49-55.jpeg"],"options":["Rare and very short projects.","Wide sharing of specialists.","Cost minimization as top priority.","Priorities set by functional heads.","A continuous flow of projects."],"id":107,"answer":4,"category":"Ситуации","keyReferences":["Variant 5, №28"]},{"number":29,"text":"Scenario: A consultant compares several companies in Kazakhstan that are considering a matrix structure. Question: For which company would a matrix be most practical?","sources":["IMG_7CDC58C72E49-25.jpeg","IMG_7CDC58C72E49-26.jpeg","IMG_7CDC58C72E49-55.jpeg","IMG_7CDC58C72E49-56.jpeg","IMG_7CDC58C72E49-77.jpeg"],"options":["A firm with little need for specialist skills.","A firm in a rapidly changing market.","A firm mass-producing one stable product.","A firm with one long project at a time.","A firm with stable, predictable demand."],"id":108,"answer":1,"category":"Ситуации","keyReferences":["Variant 5, №29"]},{"number":35,"text":"Scenario: Early in a project, a team runs weekly sessions where citizens try prototypes of a new portal and give feedback that the team uses immediately. Question: Which Lean core concept is the team mainly applying?","sources":["IMG_7CDC58C72E49-27.jpeg","IMG_7CDC58C72E49-57.jpeg"],"options":["Empower the team.","Defer decisions.","Amplify learning.","Optimize the whole.","Build quality in."],"id":109,"answer":2,"category":"Ситуации","keyReferences":["Variant 5, №35"]},{"number":36,"text":"Scenario: Team members at a bank hide failed prototypes from their leader because past mistakes were openly criticized. As a result, few new ideas are tried. Question: Which leadership task should the leader focus on first?","sources":["IMG_7CDC58C72E49-27.jpeg","IMG_7CDC58C72E49-57.jpeg"],"options":["Re-communicating the project vision often.","Providing more licences and equipment.","Adding approval steps for new prototypes.","Making experimentation safe.","Shielding the team from outside interruptions."],"id":110,"answer":3,"category":"Ситуации","keyReferences":["Variant 5, №36"]},{"number":37,"text":"Scenario: A ministry IT department removes several approval documents that nobody reads and keeps only the activities that directly help deliver the product. Question: Which idea underlying Scrum does this change reflect?","sources":["IMG_7CDC58C72E49-27.jpeg","IMG_7CDC58C72E49-57.jpeg","IMG_7CDC58C72E49-78.jpeg"],"options":["Lean thinking.","Empiricism.","Transparency.","Cross-functionality.","Self-management."],"id":111,"answer":0,"category":"Ситуации","keyReferences":["Variant 5, №37"]},{"number":38,"text":"Scenario: A state agency staffs a team in which all UX design and database work must be requested from other departments, causing week-long waits every Sprint. Question: Which Scrum Team characteristic is missing?","sources":["IMG_7CDC58C72E49-27.jpeg","IMG_7CDC58C72E49-57.jpeg","IMG_7CDC58C72E49-78.jpeg"],"options":["A single Product Owner.","Self-management.","Cross-functionality.","Small team size.","Openness."],"id":112,"answer":2,"category":"Ситуации","keyReferences":["Variant 5, №38"]},{"number":39,"text":"Scenario: In a state company, department heads regularly overrule the Product Owner's ordering of the Product Backlog, and the Developers receive conflicting priorities. Question: What does Scrum say is needed for the Product Owner to succeed?","sources":["IMG_7CDC58C72E49-27.jpeg","IMG_7CDC58C72E49-28.jpeg","IMG_7CDC58C72E49-57.jpeg","IMG_7CDC58C72E49-58.jpeg","IMG_7CDC58C72E49-78.jpeg"],"options":["Department heads should jointly own the Product Backlog with the Product Owner.","The entire organization must respect the Product Owner's decisions.","Priorities should be fixed at the start and not changed.","The Scrum Master should approve every change to item order.","Developers should order the items they find most urgent."],"id":113,"answer":1,"category":"Ситуации","keyReferences":["Variant 5, №39"]},{"number":41,"text":"Scenaria: Mid-Sprint, the Developers of a university admissions partal realize one selected item is much larger than expected, although the Sprint Goal is still achievable with less scope. Question: What does Scrum allow them to do?","sources":["IMG_7CDC58C72E49-28.jpeg","IMG_7CDC58C72E49-58.jpeg","IMG_7CDC58C72E49-78.jpeg"],"options":["Clarify and renegotiate scope with the Product Owner.","Change the Sprint Goal without involving anyone else.","Cancel the Sprint, since the forecast was wrong.","Ask the Scrum Master to extend the Sprint end date.","Lower the quality bar so all items can be finished."],"id":114,"answer":0,"category":"Теория","keyReferences":["Variant 5, №41"]},{"number":42,"text":"Scenario: The Daily Scrum of a regional akimat team is held at different times and places each day, and participants mostly report how many hours they worked. Question: What is the main purpose of the event that they are missing?","sources":["IMG_7CDC58C72E49-28.jpeg","IMG_7CDC58C72E49-31.jpeg","IMG_7CDC58C72E49-58.jpeg","IMG_7CDC58C72E49-61.jpeg","IMG_7CDC58C72E49-78.jpeg"],"options":["Re-order the Product Backlog with the Product Owner.","Report hours worked to the Scrum Master for tracking.","Demonstrate finished work to stakeholders for feedback.","Review the team's processes and Definition of Done.","Inspect Sprint Goal progress and adapt the plan."],"id":115,"answer":4,"category":"Ситуации","keyReferences":["Variant 5, №42"]},{"number":43,"text":"Scenario: in a Sprint Retrospective, a team at a mobile operator finds that failed deployments were caused by manual steps and decides to automate them. Question: What can the team do with this improvement?","sources":["IMG_7CDC58C72E49-28.jpeg","IMG_7CDC58C72E49-31.jpeg","IMG_7CDC58C72E49-58.jpeg","IMG_7CDC58C72E49-61.jpeg","IMG_7CDC58C72E49-79.jpeg"],"options":["Wait for the Product Owner at the next Review.","Implement it in the current Sprint after the Retrospective.","Ask stakeholders to approve it at the next Review.","Record it only; changes are allowed after the release.","Add it to the Sprint Backlog for the next Sprint."],"id":116,"answer":4,"category":"Ситуации","keyReferences":["Variant 5, №43"]},{"number":11,"text":"According to the Scrum Guide, which elements together make up the Sprint Backlog?","sources":["IMG_7CDC58C72E49-29.jpeg","IMG_7CDC58C72E49-59.jpeg","IMG_7CDC58C72E49-74.jpeg"],"options":["The selected items, the team's capacity and a burn-down chart.","The Product Goal, the Sprint Goal and the release schedule.","The Sprint Goal, the whole Product Backlog and the last Increment.","The Product Goal, the selected items and the Definition of Done.","The Sprint Goal, the selected items and the plan to deliver them."],"id":118,"answer":4,"category":"Теория","keyReferences":["Variant 5, №11"]},{"number":12,"text":"What must a Scrum Team do when its organization has a standard Definition of Done?","sources":["IMG_7CDC58C72E49-29.jpeg","IMG_7CDC58C72E49-59.jpeg","IMG_7CDC58C72E49-74.jpeg"],"options":["Replace it with its own definition.","Follow it as a minimum.","Ask the Product Owner to approve a lower version.","Use it only when several teams share a product.","Follow it only for items that are released."],"id":119,"answer":1,"category":"Теория","keyReferences":["Variant 5, №12"]},{"number":31,"text":"Scenario: An analyst at a fintech company in Astana first studied and internalized agile principles, then began applying agile practices in her own work. Question: What is the next step in her path to organizational change?","sources":["IMG_7CDC58C72E49-30.jpeg","IMG_7CDC58C72E49-60.jpeg","IMG_7CDC58C72E49-77.jpeg"],"options":["Practice agile techniques herself.","Fix scope and let cost and time vary.","Learn agile principles individually.","Encourage others to become agile.","Write a defined process for all teams."],"id":120,"answer":3,"category":"Ситуации","keyReferences":["Variant 5, №31"]},{"number":32,"text":"Scenario: A team split between Astana and Shymkent relies on long email threads to clarify requirements, and misunderstandings keep causing rework. Question: Which agile principle points to the best improvement?","sources":["IMG_7CDC58C72E49-30.jpeg","IMG_7CDC58C72E49-60.jpeg"],"options":["Working software measures progress best.","Simplicity is essential to every project.","Technical excellence enhances agility.","Face-to-face talk conveys information best.","Late requirement changes should be welcome."],"id":121,"answer":3,"category":"Ситуации","keyReferences":["Variant 5, №32"]},{"number":33,"text":"Scenario: An XP team merges everyone's code only once a month and then spends several days fixing code that no longer compiles or works together. Question: Which XP practice would best address this problem?","sources":["IMG_7CDC58C72E49-30.jpeg","IMG_7CDC58C72E49-60.jpeg","IMG_7CDC58C72E49-77.jpeg"],"options":["Continuous integration.","Sustainable pace.","Metaphor.","Planning games.","Collective code ownership."],"id":122,"answer":0,"category":"Ситуации","keyReferences":["Variant 5, №33"]},{"number":34,"text":"Scenario: Analysts in Astana hand designs to developers in Almaty, who hand code to testers in Shymkent. Each handoff takes extra effort to explain and transfer. Question: Which Lean waste is most evident?","sources":["IMG_7CDC58C72E49-30.jpeg","IMG_7CDC58C72E49-31.jpeg","IMG_7CDC58C72E49-60.jpeg","IMG_7CDC58C72E49-61.jpeg"],"options":["Motion.","Extra features.","Task switching.","Extra processes.","Defects."],"id":123,"answer":0,"category":"Ситуации","keyReferences":["Variant 5, №34"]},{"number":44,"text":"Scenario: A product owner of a city parking app says: 'Personas are just a nicer name for user roles such as Admin or Driver.' Question: Which statement best corrects this view?","sources":["IMG_7CDC58C72E49-31.jpeg","IMG_7CDC58C72E49-61.jpeg","IMG_7CDC58C72E49-79.jpeg"],"options":["Personas are job titles used to assign system access rights.","Personas are real customers who are quoted by name in specs.","Personas are groups of features ranked by development cost.","Personas are fictional archetypes of typical users.","Personas are team roles defined within the Scrum framework."],"id":125,"answer":3,"category":"Ситуации","keyReferences":["Variant 5, №44"]},{"number":45,"text":"Scenario: A startup in Astana needs a quick view of its key users for a planning meeting tomorrow morning, and there is no time for further research. Question: Which persona format best fits this need?","sources":["IMG_7CDC58C72E49-32.jpeg","IMG_7CDC58C72E49-62.jpeg","IMG_7CDC58C72E49-79.jpeg"],"options":["A context diagram showing all external systems.","A full demographic report from the statisties agency.","A one-page short template with key facts.","A long template with an in-depth day-in-the-life story.","A detailed use case model listing all actors."],"id":126,"answer":2,"category":"Ситуации","keyReferences":["Variant 5, №45"]},{"number":46,"text":"Scenario: An analyst writes a single persona called 'Average citizen' who is any age, lives in any region, speaks all languages and is equally at ease with mobile and desktop. Question: What is the main weakness of this persona?","sources":["IMG_7CDC58C72E49-32.jpeg","IMG_7CDC58C72E49-62.jpeg","IMG_7CDC58C72E49-79.jpeg"],"options":["It is too short to count as a persona at all.","It has too many differentiators to be ranked properly.","It is too generic to be distinct or realistic.","It was written before the product roadmap existed.","It focuses on wants instead of on motivations."],"id":127,"answer":2,"category":"Ситуации","keyReferences":["Variant 5, №46"]},{"number":47,"text":"Scenario: An analyst wants to rewrite the story 'As a citizen, I need to book a slot at a public service center so that I do not wait in a queue' in the alternative format. Question: Which version is the correct equivalent?","sources":["IMG_7CDC58C72E49-32.jpeg","IMG_7CDC58C72E49-62.jpeg"],"options":["'In order to book a slot, as a citizen, I need to avoid a queue.'","'In order to avoid a queue, as a citizen, I need to book a slot.!","'Given a free slot, when a citizen books it, the queue is avoided.'","'Citizen books a slot, system confirms, queue time goes down.'","'As a service center, I need slots booked so that queues shrink."],"id":128,"answer":1,"category":"Ситуации","keyReferences":["Variant 5, №47"]},{"number":48,"text":"Scenario: An akimat's appointment-booking story was accepted, but citizens later found they could book visits on public holidays. Nobody had stated what the feature should and should not allow. Question: What was most likely missing?","sources":["IMG_7CDC58C72E49-32.jpeg","IMG_7CDC58C72E49-62.jpeg","IMG_7CDC58C72E49-79.jpeg"],"options":["A product roadmap for the next year.","A more detailed title on the story card.","A larger team to deliver the story.","A longer persona template for citizens.","Clear acceptance criteria for the story."],"id":129,"answer":4,"category":"Ситуации","keyReferences":["Variant 5, №48"]},{"number":49,"text":"Scenario: After several joint story-writing sessions, developers and the operations staff of a bank understand each other's work much better and feel more committed to the product. Question: Which strength of user stories does this illustrate?","sources":["IMG_7CDC58C72E49-32.jpeg","IMG_7CDC58C72E49-62.jpeg","IMG_7CDC58C72E49-63.jpeg","IMG_7CDC58C72E49-79.jpeg"],"options":["Stories guarantee that all estimates will be accurate.","Stories cut the number of team meetings down to zero.","Joint work on stories builds shared understanding.","Stories allow the team to skip backlog refinement.","Stories move responsibility for value to the developers."],"id":130,"answer":2,"category":"Ситуации","keyReferences":["Variant 5, №49"]},{"number":1,"text":"A logical grouping of contract tasks that have not yet been identified or authorized is held in which budget?","sources":["IMG_7CDC58C72E49-42.jpeg"],"options":["The distributed budget.","The management reserve.","The undistributed budget.","The unallocated budget.","The performance budget."],"id":137,"answer":3,"category":"Теория","keyReferences":["Variant 2, №1","Variant 4, №1"],"keyNote":"Исправлено по add: Variant 4, №1 — The unallocated budget."},{"number":2,"text":"Why is the earned value measurement system described as an early warning system?","sources":["IMG_7CDC58C72E49-42.jpeg"],"options":["It compares final cost with the bid after closure.","It shows deviations from plan while still small.","It sets the management reserve for each phase.","It predicts the exact final cost with certainty.","It replaces periodic re-estimation of the cost."],"id":138,"answer":1,"category":"Теория","keyReferences":["Variant 2, №2","Variant 4, №2"]},{"number":3,"text":"Which list gives the reasons why people form groups?","sources":["IMG_7CDC58C72E49-42.jpeg"],"options":["Productivity, flexibility, diversity and quality.","Structure, status, roles, norms and leadership.","Needs, proximity, attraction, goals and economics.","Forming, storming, norming, performing, adjourning.","Cost, schedule, technical performance and risk."],"id":139,"answer":2,"category":"Теория","keyReferences":["Variant 4, №3"]},{"number":4,"text":"Which term means being answerable for completing a specific assignment satisfactorily?","sources":["IMG_7CDC58C72E49-42.jpeg"],"options":["Accountability.","Responsibility.","Coordination.","Integration.","Authority."],"id":140,"answer":0,"category":"Теория","keyReferences":["Variant 4, №4"]},{"number":6,"text":"In a matrix, what is the project manager accountable for?","sources":["IMG_7CDC58C72E49-43.jpeg"],"options":["The overall success of the project.","The technical excellence of each discipline.","Setting the company's overhead rates.","Merit reviews of all functional staff.","Resolving conflicts between all projects."],"id":141,"answer":0,"category":"Теория","keyReferences":["Variant 4, №6"]},{"number":7,"text":"Which Agile Manifesto value best reflects the view that skilled team members matter more than methods?","sources":["IMG_7CDC58C72E49-43.jpeg"],"options":["Processes and tools over individuals and interactions.","Individuals and interactions over processes and tools.","Customer collaboration over contract negotiation.","Responding to change over following a plan.","Working software over comprehensive documentation."],"id":142,"answer":1,"category":"Теория","keyReferences":["Variant 4, №7"]},{"number":9,"text":"Which statement is one of the eight DSDM principles?","sources":["IMG_7CDC58C72E49-43.jpeg"],"options":["Limit work in progress.","Defer decisions.","Expect uncertainty.","Sustainable pace.","Demonstrate control."],"id":143,"answer":4,"category":"Теория","keyReferences":["Variant 4, №9"]},{"number":10,"text":"According to the Scrum Guide, what do the Scrum values give direction to?","sources":["IMG_7CDC58C72E49-43.jpeg"],"options":["The length of each Sprint.","The content of the Definition of Done.","The selection of team tools.","The order of Product Backlog items.","The team's work, actions and behavior."],"id":144,"answer":4,"category":"Теория","keyReferences":["Variant 4, №10"]},{"number":11,"text":"What is the maximum timebox for Sprint Planning in a one-month Sprint?","sources":["IMG_7CDC58C72E49-43.jpeg"],"options":["Eight hours.","Three hours.","Two hours.","Four hours.","Fifteen minutes."],"id":145,"answer":0,"category":"Теория","keyReferences":["Variant 4, №11"]},{"number":12,"text":"According to the Scrum Guide, who is responsible for sizing Product Backlog items?","sources":["IMG_7CDC58C72E49-43.jpeg"],"options":["The organization's senior management.","The Scrum Master, who coaches the team.","The key stakeholders, who fund the product.","The Developers who will do the work.","The Product Owner, who orders the items."],"id":146,"answer":3,"category":"Теория","keyReferences":["Variant 4, №12"]},{"number":13,"text":"Which persona element states what makes one persona unique compared with another persona?","sources":["IMG_7CDC58C72E49-44.jpeg"],"options":["Name and image.","Differentiators.","Needs.","Motivations.","Short template."],"id":147,"answer":1,"category":"Теория","keyReferences":["Variant 4, №13"]},{"number":14,"text":"Under INVEST, what makes a user story Testable?","sources":["IMG_7CDC58C72E49-44.jpeg"],"options":["It can be delivered apart from other features.","The team can negotiate how to deliver it.","A stakeholder can validate it objectively.","The team can estimate it from past experience.","It shows the value it brings to the customer."],"id":148,"answer":2,"category":"Теория","keyReferences":["Variant 4, №14"]},{"number":15,"text":"What style is recommended for the title on a user story card?","sources":["IMG_7CDC58C72E49-44.jpeg"],"options":["A number from the product backlog.","A short acceptance criterion.","A noun naming the system module.","An active-verb goal phrase.","The name of the main persona."],"id":149,"answer":3,"category":"Теория","keyReferences":["Variant 4, №15"]},{"number":16,"text":"Scenario: At an IT startup in Astana, hours worked and money spent are entered into the project records only at the end of each quarter, often two months after the work was done. Question: Which requirement of effective cost and schedule control is weakest here?","sources":["IMG_7CDC58C72E49-44.jpeg"],"options":["Thorough planning of the work to be done.","Timely accounting of progress and costs.","Disciplined authorization of spending.","Clear communication of the task scope.","Good estimating of labor and costs."],"id":150,"answer":1,"category":"Ситуации","keyReferences":["Variant 4, №16"]},{"number":17,"text":"Scenario: Each month the project manager of a digital-ID project presents status, variances and forecasts to the client ministry and to the company's executive board. Question: Which phase of the operating cycle does this represent?","sources":["IMG_7CDC58C72E49-44.jpeg"],"options":["Cost analysis.","Customer and management reporting.","Cost data collection and reporting.","The planning cycle.","Work authorization and release."],"id":151,"answer":1,"category":"Ситуации","keyReferences":["Variant 4, №17"]},{"number":18,"text":"Scenario: A school-digitization project reports, in million tenge: BCWS = 80, BCWP = 80, ACWP = 70 Question: What can be concluded from CV and SV?","sources":["IMG_7CDC58C72E49-45.jpeg"],"options":["Over budget by 10 and exactly on schedule.","Over budget by 10 and ahead of schedule by 10.","On budget and ahead of schedule by 10.","Under budget by 10 and behind schedule by 10.","Under budget by 10 and exactly on schedule."],"id":152,"answer":4,"category":"Ситуации","keyReferences":["Variant 4, №18"]},{"number":19,"text":"Scenario: A fintech startup's project has CPI = 1.1 and SPI = 0.75. Question: What should be the main focus of corrective action?","sources":["IMG_7CDC58C72E49-45.jpeg"],"options":["Improving the productivity of the work force.","Reducing the burn rate of the budget.","Re-baselining the budget at completion.","Improving the timeliness of physical progress.","Releasing the management reserve."],"id":153,"answer":3,"category":"Ситуации","keyReferences":["Variant 4, №19"]},{"number":20,"text":"Scenario: A project was originally planned to last 12 months, and its SPI is now 0.8. Question: What is the new estimated project length?","sources":["IMG_7CDC58C72E49-45.jpeg"],"options":["12.8 months.","10 months.","14 months.","9.6 months.","15 months."],"id":154,"answer":4,"category":"Ситуации","keyReferences":["Variant 4, №20"]},{"number":21,"text":"Scenario: The team that launched an akimat's open-data portal has delivered all tasks. Members hold a final meeting, and some express sadness about losing daily contact. Question: Which stage of group development is this?","sources":["IMG_7CDC58C72E49-45.jpeg"],"options":["Norming.","Performing.","Storming.","Forming.","Adjourning."],"id":155,"answer":4,"category":"Ситуации","keyReferences":["Variant 4, №21"]},{"number":22,"text":"Scenario: At an akimat, management, the IT team and the analyst herself each have a different picture of what the 'business analyst position should involve. Question: How is this situation best explained?","sources":["IMG_7CDC58C72E49-45.jpeg"],"options":["One role can be perceived in up to three ways.","The team has fallen into groupthink.","The team has reached the adjourning stage.","The analyst is going through the storming stage.","The analyst has joined an informal interest group."],"id":156,"answer":0,"category":"Ситуации","keyReferences":["Variant 4, №22"]},{"number":23,"text":"Scenario: An akimat's digital projects are delivered on time and to specification, but the groups and individuals involved are not satisfied with what they achieved. Question: What does this pattern most likely suggest?","sources":["IMG_7CDC58C72E49-46.jpeg"],"options":["No change is needed because targets were met.","The akimat has found its ideal permanent structure.","The projects were scoped far too conservatively.","Met targets can still hide a structural mismatch.","Staff satisfaction has nothing to do with structure."],"id":157,"answer":3,"category":"Ситуации","keyReferences":["Variant 4, №23"]},{"number":24,"text":"Scenario: At a bank in Almaty, a project manager and a functional manager have stopped blaming cach other, and each has openly admitted their part in a delayed release. Question: What is the next stage in the growth of their trust?","sources":["IMG_7CDC58C72E49-46.jpeg"],"options":["Denying that the problem exists at all.","Meeting face-to-face to solve the problem.","Blaming each other once the problem surfaces.","Anticipating problems before they occur.","Escalating the problem to the general manager."],"id":158,"answer":1,"category":"Ситуации","keyReferences":["Variant 4, №24"]},{"number":25,"text":"Scenario: A regional bank is debating whether to keep its classical functional structure. Question: Which statement is an advantage of that structure?","sources":["IMG_7CDC58C72E49-46.jpeg"],"options":["Projects rarely fall behind their schedules.","One individual is responsible for the total project.","Ideas are strongly oriented toward the ongoing projects.","Vertical communication channels are well established.","Decisions are balanced across all functional groups."],"id":159,"answer":3,"category":"Ситуации","keyReferences":["Variant 4, №25"]},{"number":26,"text":"Scenario: In a functional engineering firm, every dispute about a joint design is settled in favor of the largest and most powerful department. Question: Which weakness of the traditional structure is this?","sources":["IMG_7CDC58C72E49-46.jpeg"],"options":["There is no technical control over the design.","Personnel cannot be reused across projects.","Decisions favor the strongest units.","There are too many project managers involved.","Communication channels are poorly established."],"id":160,"answer":2,"category":"Ситуации","keyReferences":["Variant 4, №26"]},{"number":27,"text":"Scenario: An engineering division has a liaison department that handles engineering changes between its units. A conflict now arises between the engineering and manufacturing divisions. Question: How is this conflict most likely resolved?","sources":["IMG_7CDC58C72E49-46.jpeg","IMG_7CDC58C72E49-48.jpeg"],"options":["The engineering head decides alone.","The customer is asked to arbitrate.","It is referred to upper management.","The task force votes on a solution.","The liaison department resolves it alone."],"id":161,"answer":2,"category":"Ситуации","keyReferences":["Variant 4, №27"]},{"number":34,"text":"Scenario: Without being asked, a team adds an animated 3D dashboard to an akimat's reporting system. The akimat never uses it. Question: Which Lean waste does this represent?","sources":["IMG_7CDC58C72E49-48.jpeg"],"options":["Defects.","Partially done work.","Motion.","Extra features.","Extra processes."],"id":162,"answer":3,"category":"Ситуации","keyReferences":["Variant 4, №34"]},{"number":35,"text":"Scenario: Instead of inspecting the finished system at the end, a team reviews and tests every piece of work as soon as it is produced, at each stage of development. Question: Which Lean core concept does this reflect?","sources":["IMG_7CDC58C72E49-48.jpeg"],"options":["Defer decisions.","Optimize the whole.","Eliminate waste.","Build quality in.","Deliver fast."],"id":163,"answer":3,"category":"Ситуации","keyReferences":["Variant 4, №35"]},{"number":36,"text":"Scenario: Two senior developers on a ministry project openly disagree about the system architecture and debate it in a team meeting. Question: How should an agile leader view this conflict?","sources":["IMG_7CDC58C72E49-48.jpeg"],"options":["As a positive step in team development.","As acceptable only if a manager chairs it.","As a reason to impose a final decision.","As a sign the team should be split up.","As a matter to settle outside the team."],"id":164,"answer":0,"category":"Ситуации","keyReferences":["Variant 4, №36"]},{"number":37,"text":"Scenario: Halfway through a Sprint, the Developers of a fintech startup discover that a payment API they are integrating behaves differently than they assumed. Question: When does Scrum expect the team to adjust its plan and work?","sources":["IMG_7CDC58C72E49-48.jpeg","IMG_7CDC58C72E49-50.jpeg"],"options":["At the end of the release, when all data is available.","As soon as possible, to minimize further deviation.","Only after the Product Owner cancels the Sprint.","At the Sprint Review, after stakeholders give feedback.","At the next Sprint Retrospective, after discussion."],"id":165,"answer":1,"category":"Ситуации","keyReferences":["Variant 4, №37"]},{"number":43,"text":"Scenario: For a one-month Sprint, a team schedules a four-hour Sprint Review and a four-hour Sprint Retrospective. Question: Which statement is correct?","sources":["IMG_7CDC58C72E49-50.jpeg"],"options":["The Review exceeds its two-hour maximum.","The Retrospective exceeds its three-hour maximum.","Both are within their timeboxes for a one-month Sprint.","The Review exceeds its three-hour maximum.","Both events exceed their two-hour maximum."],"id":166,"answer":1,"category":"Ситуации","keyReferences":["Variant 4, №43"]},{"number":44,"text":"Scenario: An IT outsourcing company in Astana builds a mobile app for the tax authority, but its developers are not allowed to meet taxpayers directly Question: Which technique best helps the team understand value from the taxpayer's point of view?","sources":["IMG_7CDC58C72E49-50.jpeg"],"options":["Personas.","Story decomposition.","Product roadmap.","Regression testing.","Velocity tracking."],"id":167,"answer":0,"category":"Ситуации","keyReferences":["Variant 4, №44"]},{"number":45,"text":"Scenario: An analyst for a regional akimat's social-benefits portal has official statistics on the age, district and income of benefit applicants. Question: How should she best use this data?","sources":["IMG_7CDC58C72E49-50.jpeg"],"options":["As input used only for the project cost estimate.","As the product vision statement for the portal.","As the acceptance criteria for each user story.","As a replacement for personas, since statistics are more exact.","As a starting point for a representative pool of personas."],"id":168,"answer":4,"category":"Ситуации","keyReferences":["Variant 4, №45"]},{"number":46,"text":"Scenario: A team designing an online pension calculator plans to use personas as the only source of user insight for the whole project. Question: Which is the strongest argument against this plan?","sources":["IMG_7CDC58C72E49-50.jpeg"],"options":["Personas are not a substitute for real user input.","Personas cannot be ranked by the benefit they get.","Personas can only be used by the product owner.","Personas cannot include images or names of users.","Personas must always start with the long template."],"id":169,"answer":0,"category":"Ситуации","keyReferences":["Variant 4, №46"]},{"number":47,"text":"Scenario: A junior developer at a fintech startup believes that only the product owner may write user stories and that every backlog item must be a user story. Question: Which statement is correct?","sources":["IMG_7CDC58C72E49-50.jpeg"],"options":["Only the product owner writes stories, and every item must be a story.","Several roles may write stories; not every item must be one.","Testers write stories after the feature has already been built.","Only customers write stories, and other items stay off the backlog.","Only developers write stories, since they estimate and deliver them."],"id":170,"answer":1,"category":"Ситуации","keyReferences":["Variant 4, №47"]},{"number":19,"text":"Scenario: A telecom project in Karaganda reports BCWS = 750, BCWP = 600 and ACWP = 500. Question: Which pair of indices is correct?","sources":["IMG_7CDC58C72E49-75.jpeg"],"options":["CPI = 1.2 and SPI = 1.25.","CPI = 0.8 and SPI = 1.2.","CPI = 0.8 and SPI = 1.25.","CPI = 1.25 and SPI = 0.8.","CPI = 1.2 and SPI = 0.8."],"id":174,"answer":4,"category":"Ситуации","keyReferences":["Variant 5, №19"]},{"number":20,"text":"Scenario: A bank’s CRM project has BAC = 800, BCWP = 400 and ACWP = 500 (thousand dollars). Question: If current cost efficiency continues, what is the variance at completion?","sources":["IMG_7CDC58C72E49-76.jpeg"],"options":["+100.","-200.","-250.","+200.","-100."],"id":175,"answer":1,"category":"Ситуации","keyReferences":["Variant 5, №20"]},{"number":25,"text":"Scenario: A manufacturer in Karaganda produces standard products in large volumes within established specifications and runs very few one-off projects. Question: Why is the traditional structure a reasonable fit here?","sources":["IMG_7CDC58C72E49-76.jpeg"],"options":["It speeds up decisions that cross departments.","It suits mass production within set specifications.","It gives each project manager full line authority.","It lets staff be dedicated to a single project.","It provides a strong focal point for each customer."],"id":177,"answer":1,"category":"Ситуации","keyReferences":["Variant 5, №25"]},{"number":30,"text":"Scenario: A bank in Almaty planned its new mobile app the way it plans branch construction, fixing every step in advance. Three months later, many requirements had changed and the plan was obsolete. Question: What is the most likely root cause of the problem?","sources":["IMG_7CDC58C72E49-77.jpeg"],"options":["A defined process was used for uncertain work.","The developers lacked a detailed enough upfront plan.","The team used too many short iterations and increments.","The sponsor approved the project budget too early.","The bank should have hired more construction experts."],"id":178,"answer":0,"category":"Ситуации","keyReferences":["Variant 5, №30"]},{"number":40,"text":"Scenario: A newly appointed Scrum Master in an akimat IT department approves vacations, sets individual KPIs for each Developer and reports their personal performance to management. Question: Which description of the Scrum Master shows that this behavior is wrong?","sources":["IMG_7CDC58C72E49-78.jpeg"],"options":["The team member who decides how work is done.","A true leader who serves the Scrum Team.","The person who orders the Product Backlog.","The line manager accountable for each Developer","A coordinator who reports progress to management."],"id":182,"answer":1,"category":"Ситуации","keyReferences":["Variant 5, №40"]},{"number":50,"text":"Scenario: Decomposing the epic 'Online onboarding for new bank clients' produced 40 child stories, some outdated and a few contradicting each other Question: What should the analyst do?","sources":["IMG_7CDC58C72E49-79.jpeg"],"options":["Ask developers to choose which stories to implement.","Merge all child stories back into a single large epic.","Turn the child stories into personas for each group.","Organize the child stories to keep them current.","Stop decomposition and deliver the epic in one iteration."],"id":184,"answer":3,"category":"Ситуации"},{"id":185,"number":null,"text":"Scenario: A team building an e-government portal for registering small businesses has no direct contact with entrepreneurs. The analyst describes Aigerim, 34, owner of a bakery in Shymkent, with her goals, skill level and a typical working day. Question: What is the main purpose of creating this description?","options":["To define the acceptance tests for the registration form.","To record the legal rules the registration portal must comply with.","To empathize with users and align the portal with their needs.","To estimate the development effort for each portal feature.","To replace later usability testing with real entrepreneurs."],"answer":2,"category":"Ситуации","sources":["IMG_7CDC58C72E49-6.jpeg"],"keyReferences":["Variant 1, №44"]},{"id":186,"number":null,"text":"Scenario: To save time, a team designing a city bus app creates one persona that combines traits common to students, pensioners, tourists and commuters. Question: What risk does this create?","options":["A generic persona that tries to suit everyone at once.","A delay because long templates take months to complete.","Requirements that reflect only one department’s opinion.","A persona too narrow to write any user stories from.","Too many personas that quickly inflate the product backlog."],"answer":0,"category":"Ситуации","sources":["IMG_7CDC58C72E49-6.jpeg"],"keyReferences":["Variant 1, №46"]},{"id":187,"number":47,"text":"Scenario: A university portal team reviews five backlog entries to find the one written as a proper user story. Question: Which entry correctly states the role, the needed feature and the value?","options":["As a student, so that I can plan, the timetable needs a new database table.","In order to see the exam timetable, I need a new database table.","As the timetable system, I need to show exams so that students can plan.","As a student, I need to see my exam timetable so that I can plan.","As a student, I need to see my exam timetable."],"answer":3,"category":"Ситуации","sources":["IMG_7CDC58C72E49-18.jpeg"],"keyReferences":["Variant 3, №47"]},{"id":188,"number":16,"text":"Scenario: A ministry project has a detailed plan, sound estimates, an approved budget and up-to-date cost records. However, actual progress and spending are compared with the baseline only once, at project closure. Question: What is the most appropriate improvement to the control system?","options":["Prepare a more detailed work breakdown structure.","Compare actuals with plan frequently.","Re-estimate the original budget with a new method.","Communicate the project scope to the team again.","Ask the vendor to record costs more often."],"answer":1,"category":"Ситуации","sources":["IMG_7CDC58C72E49-23.jpeg"],"keyReferences":["Variant 5, №16"]}];
